//! Membrane pins — the solve offers ITSELF (Law II in full).
//!
//! The proved family crosses the membrane whole and is measured at
//! one uniform fiber rank; synthesis (`claim_for`) survives only as
//! the backfill fallback. These pins hold the measurement law; the
//! live acceptance is a tile solve reaching the observer as a net
//! install or an honest withhold.

use scribe::membrane::{claim_for, family_rank, measure_at, Grid};

fn g(rows: &[&[u8]]) -> Grid {
    rows.iter().map(|r| r.to_vec()).collect()
}

/// One family, one fiber: the rank is the max hue anywhere in the
/// family + 1, so a hue present on one chart is representable on
/// every chart — family-glue's "fixedness is a constraint" needs the
/// fixed hue to EXIST on the chart that holds it fixed.
#[test]
fn family_measured_at_one_uniform_rank() {
    let pairs = vec![
        (g(&[&[1, 2], &[3, 4]]), g(&[&[2, 1], &[4, 3]])),
        (g(&[&[0, 9]]), g(&[&[9, 0]])), // hue 9 lives only on this chart
    ];
    let rank = family_rank(&pairs);
    assert_eq!(rank, 10, "max hue 9 → rank 10 across the whole family");
    for (a, b) in &pairs {
        let ma = measure_at(a, rank).expect("input measures at family rank");
        let mb = measure_at(b, rank).expect("output measures at family rank");
        assert_eq!(ma.occupancy().len(), a.len() * a[0].len());
        assert_eq!(mb.occupancy().len(), b.len() * b[0].len());
    }
}

/// Ragged paper is not a grid: refusal, never a guess.
#[test]
fn ragged_grid_refuses_measurement() {
    let ragged: Grid = vec![vec![1, 2, 3], vec![4, 5]];
    assert!(measure_at(&ragged, 10).is_none());
}

/// A hue at the fiber edge measures; past the family rank refuses at
/// the peel's own door (directions bounded by fiber rank).
#[test]
fn rank_bounds_are_the_peel_law() {
    let grid = g(&[&[7]]);
    assert!(measure_at(&grid, 8).is_some(), "hue 7 fits rank 8");
    assert!(measure_at(&grid, 7).is_none(), "hue 7 refused at rank 7");
}

/// The backfill fallback still peels what the v1 era could, and still
/// names what it cannot — its coverage limit is that era's, not the
/// proved-pair path's.
#[test]
fn backfill_claim_for_unchanged() {
    assert!(claim_for("rotate180").is_some());
    assert!(claim_for("recolor[1,0,2,3,4,5,6,7,8,9]").is_some());
    assert!(
        claim_for("recolor[1,0,2,3,4,5,6,7,8,9] → flip_h").is_none(),
        "composite stays backfill-unreachable; live solves carry pairs"
    );
}
